def FB(q): return f"affine(clampall(scale(overlapall({q}, chunkTexts, stop), 4), 0, 1), 0.7, 0.2)"
def VEC(q): return f"roundall(lookup(semSims, {q}, {FB(q)}), 3)"
def ex(*qs): return [{'pt':q['pt'],'en':q['en']} for q in qs]
Q=[q for q,_,_ in QUESTIONS]
OFF={'pt':'Qual o horário da academia da empresa?','en':'What are the company gym’s opening hours?'}
OFFSIMS=[0.73,0.71,0.71,0.72,0.73,0.72,0.74,0.73,0.71,0.72,0.71,0.71]

